import type { EngineInterface as Engine, Register } from 'claude-code'

import { formatUsage } from './format'

const ENABLED_KEY = 'enabled'
const DEFAULT_INTERVAL_SECONDS = 30
const MIN_INTERVAL_SECONDS = 5

// The running refresh timer's cancel, while the overlay is on.
let cancel: (() => void) | undefined

// The overlay is a toast: the engine's only layer that floats over the
// transcript's top-right corner. Each refresh posts a toast that lives for one
// interval, so the next one takes its place instead of stacking under it.
async function show($: Engine, intervalMs: number) {
  const usage = await $.session.usage()
  const now = await $.clock.now()
  $.ui.toast(formatUsage(usage, now), { timeoutMs: intervalMs })
}

async function start($: Engine, intervalMs: number) {
  if (cancel) {
    return
  }
  const timer = $.clock.every(intervalMs, () => void show($, intervalMs))
  cancel = () => timer.cancel()
  await show($, intervalMs)
}

function stop() {
  cancel?.()
  cancel = undefined
}

async function isEnabled($: Engine) {
  return (await $.store.get(ENABLED_KEY)) !== false
}

export const register: Register = (on, options) => {
  const configured = Number(options.intervalSeconds ?? DEFAULT_INTERVAL_SECONDS)
  const seconds = Number.isFinite(configured) ? configured : DEFAULT_INTERVAL_SECONDS
  const intervalMs = Math.max(MIN_INTERVAL_SECONDS, seconds) * 1000

  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'usage-overlay',
      description: 'Toggle the usage overlay in the top-right corner (on, off, or now)',
    })
    if (await isEnabled($)) {
      await start($, intervalMs)
    }

    return next(e)
  })

  on('command.run', { command: 'usage-overlay' }, async ($, e) => {
    const arg = e.args.trim().toLowerCase()

    if (arg === 'now') {
      await show($, intervalMs)
      return { text: 'Usage overlay refreshed.' }
    }

    const enable = arg === 'on' ? true : arg === 'off' ? false : !(await isEnabled($))
    await $.store.set(ENABLED_KEY, enable)
    if (enable) {
      await start($, intervalMs)
      return { text: `Usage overlay on, refreshing every ${intervalMs / 1000}s.` }
    }
    stop()

    return { text: 'Usage overlay off.' }
  })
}

