import type { SessionUsage } from 'claude-code'

const WINDOW_LABELS: Record<string, string> = {
  five_hour: '5h',
  seven_day: '7d',
  spend_limit: 'spend',
}

// Formats a duration in milliseconds as "2h10m", "45m" or "3d4h".
export const formatDuration = (ms: number): string => {
  const minutes = Math.max(0, Math.round(ms / 60_000))
  const days = Math.floor(minutes / 1440)
  const hours = Math.floor((minutes % 1440) / 60)
  const mins = minutes % 60

  if (days > 0) {
    return `${days}d${hours}h`
  }
  if (hours > 0) {
    return `${hours}h${String(mins).padStart(2, '0')}m`
  }

  return `${mins}m`
}

// Formats a token count as "850", "45k" or "1.2M".
export const formatTokens = (tokens: number): string => {
  if (tokens >= 1_000_000) {
    return `${(tokens / 1_000_000).toFixed(1)}M`
  }
  if (tokens >= 1_000) {
    return `${Math.round(tokens / 1_000)}k`
  }

  return String(tokens)
}

// Builds the one line the overlay shows, e.g.
// "5h 23% ↻2h10m · 7d 41% ↻3d4h · ctx 45k 23% · $1.23".
export const formatUsage = (usage: SessionUsage, now: number): string => {
  const parts: string[] = []

  for (const limit of usage.rateLimits) {
    const label = WINDOW_LABELS[limit.kind] ?? limit.kind
    let part = `${label} ${Math.round(limit.percentUsed)}%`
    const resetsAt = limit.resetsAt ? Date.parse(limit.resetsAt) : NaN
    if (!Number.isNaN(resetsAt) && resetsAt > now) {
      part += ` ↻${formatDuration(resetsAt - now)}`
    }
    parts.push(part)
  }

  const { context } = usage
  if (context.tokens !== undefined) {
    const percent = context.percent !== undefined ? ` ${context.percent}%` : ''
    parts.push(`ctx ${formatTokens(context.tokens)}${percent}`)
  }

  if (usage.cost) {
    parts.push(`$${usage.cost.usd.toFixed(2)}`)
  }

  return parts.length > 0 ? parts.join(' · ') : 'no usage yet'
}

